export function applyDiscount(cart: Cart, code: string): Cart {
  // First we look up the rate for the code.
  // Then we apply it to the cart total.
  // Note: this used to round per line item,
  // but the rounding moved to checkout.
  const rate = rateFor(code);
  return { ...cart, total: cart.total * (1 - rate) };
}

